function validateOverrides(data,rows=[]){const codes=new Set(data.profiles.map(p=>p.id)),seen=new Set();if(!Array.isArray(rows))fail('Kompletteringar ska vara en lista.');return rows.map(row=>{if(!row||typeof row!=='object'||!sameKeys(row,{deso:0,mode:0,pkm_year:0,year:0,source:0}))fail('En komplettering ska ha deso, mode, pkm_year, year och source.');if(!codes.has(row.deso)||!MODE_IDS.includes(row.mode))fail('Komplettering: okänd DeSO eller färdmedelskod.');const key=row.deso+'|'+row.mode;if(seen.has(key))fail('Dubbelt värde för '+key);seen.add(key);if(row.year!==data.base_year)fail('Kompletteringar ska avse basår 2024; år blandas inte automatiskt.');finite(row.pkm_year,'Personkilometer per år');if(typeof row.source!=='string'||!row.source.trim())fail('Kompletteringens källa saknas.');return copy(row);});}
