function renderMap(){return hero('Karta & områden','Malmö i 250-metersrutor','Rutorna är klippta mot kust och DeSO. Klimat- och hushållsprofilen är densamma inom ett DeSO. Centrumavståndet i tillgänglighetsindexet beräknas däremot från varje rutfragments analyspunkt.')+'<div class="filter-row"><div><label for="region-select">Fokusera på område</label><select id="region-select">'+regionOptions(state.selected)+'</select></div><div>'+button('Hämta kartlager som GeoJSON','export-geojson')+'</div></div>'+mapPanel()+'<div id="map-details">'+detailsPanel()+'</div>'+note('Rutorna saknar egna observerade hushållsantal. Utsläpp per ruta och rutbaserade kommunsummor beräknas därför inte. DeSO- och kommunsummor finns under Resultat & jämförelse.',false,true);}
function detailsPanel(){const r=selectedRow();if(!r)return '<section class="panel"><h3>Välj ett område i kartan</h3><p class="mini-text">Klicka på en ruta eller välj ett DeSO i listan. Detaljerna avser områdets boende, inte en identifierad byggnad eller ett visst hushåll.</p></section>';const ac=M.availability(D,state.config,pBy[r.id]);return '<section class="panel"><div class="section-head" style="margin-top:0"><div><div class="eyebrow">'+r.id+'</div><h2>'+esc(r.name)+'</h2></div><button class="btn small" data-action="clear-selection">Visa hela Malmö</button></div><div class="cards">'+kpi('Tillgänglighetsindex',fmt(r.availability),'av 100','Områdets värde · lika komponentvikter vid standardval')+kpi('Klimat per hushåll',fmt(r.annual_ton_hh,2),'ton CO₂e/år',fmt(r.households)+' hushåll i DeSO')+kpi('Hushållsstorlek',fmt(r.household_size,2),'personer','Folkmängd dividerat med registrerade hushåll')+kpi('Bilinnehav',fmt(r.cars_per_household,2),'bilar/hushåll',fmt(r.cars)+' privatregistrerade personbilar')+'</div><div class="three-col">'+Object.entries(ac.parts).map(([k,v])=>'<div class="summary-pair"><span>'+({supply:'Kollektivtrafikutbud',service:'Närservice',node:'Kollektivtrafiknod',centre:'Centrumavstånd'})[k]+'</span><strong>'+fmt(v)+' / 100</strong></div>').join('')+'</div><p class="mini-text">Ekonomisk standard: '+fmt(r.income)+' tkr, median. Service: '+fmt(r.service_km,2)+' km fågelväg. Kollektivtrafikutbud: '+fmt(r.transit_supply,1)+' planerade avgångar/timme inom 500 m. Detta är inte restidsbaserad arbetsplatstillgänglighet.</p></section>';}
function renderResults(){const r=selectedSubject(),name=state.selected?selectedRow().name:'Hela Malmö';return hero('Resultat & jämförelse','Jämför hushållens transportprofil','Summor beräknas på DeSO-nivå. Alla färdmedel i RVU ingår, även flyg och den ospecificerade gruppen Övrigt. Faktorerna och systemgränserna kan granskas och ändras.')+'<div class="filter-row"><div><label for="region-select">Resultat för</label><select id="region-select">'+regionOptions(state.selected)+'</select></div><div>'+button('Hämta DeSO-resultat · CSV','export-csv')+'</div><div>'+button('Hämta hela beräkningen · JSON','export-result')+'</div></div><div class="cards">'+kpi('Årsutsläpp',fmt(r.annual_ton,1),'ton CO₂e',esc(name)+' · '+state.config.start_year)+kpi('Per hushåll och år',fmt(r.annual_ton_hh,2),'ton CO₂e','Samma hushållsantal som i basåret')+kpi('Per invånare och år',fmt(r.annual_ton_person,2),'ton CO₂e','Den faktiska folkmängden i nämnaren')+kpi('Per hushåll under perioden',fmt(r.period_ton_hh,1),'ton CO₂e',state.config.years+' års summerade utsläpp')+'</div>'+charts(r)+uncertaintyPanel()+comparisonPanel()+'<section class="panel"><div class="section-head" style="margin-top:0"><h2>Samtliga DeSO</h2><input id="table-search" type="text" placeholder="Sök namn eller DeSO-kod" aria-label="Sök områden" value="'+esc(state.tableSearch)+'"></div><div id="results-table">'+resultsTable()+'</div></section>'+note('Lägre utsläpp kan bero på hushållsstorlek, bilinnehav, inkomst och begränsade resmöjligheter. Klimatrankningen ska därför läsas tillsammans med tillgänglighet och sociala förutsättningar. Detta är inte en kausalt skattad marginaleffekt av ny bebyggelse.',true,true);}
function resultsTable(){const search=state.tableSearch.toLowerCase(),rs=state.result.areas.filter(r=>(r.id+' '+r.name).toLowerCase().includes(search)).sort((a,b)=>(a.annual_ton_hh??Infinity)-(b.annual_ton_hh??Infinity));return '<div class="table-scroll"><table><thead><tr><th>DeSO / områdesnamn</th><th class="num">Index</th><th class="num">Bilar/hh</th><th class="num">Personer/hh</th><th class="num">ton CO₂e/(hh·år)</th><th class="num">ton CO₂e/år</th><th class="num">ton CO₂e/hh, period</th></tr></thead><tbody>'+rs.map(r=>'<tr><td><button class="link-button" data-select="'+r.id+'">'+r.id+'</button><small>'+esc(r.name)+'</small></td><td class="num">'+fmt(r.availability)+'</td><td class="num">'+fmt(r.cars_per_household,2)+'</td><td class="num">'+fmt(r.household_size,2)+'</td><td class="num">'+fmt(r.annual_ton_hh,2)+'</td><td class="num">'+fmt(r.annual_ton,1)+'</td><td class="num">'+fmt(r.period_ton_hh,1)+'</td></tr>').join('')+'</tbody></table></div><p class="mini-text">Sorterad efter beräknad klimatpåverkan per hushåll. Index och klimat har olika betydelser och ska inte blandas till en enda rangordning.</p>';}
function uncertaintyPanel(){const u=state.uncertainty,subject=selectedRow(),s=u?(subject?u.areas[subject.id].annual:u.city_annual):null,denom=subject?subject.households:state.result.city.households;return '<section class="panel"><div class="section-head" style="margin-top:0"><div><h2>Osäkerhet i antagandena</h2><p>Monte Carlo med valda variationskoefficienter · '+state.config.draws+' dragningar</p></div>'+button(u?'Beräkna på nytt':'Beräkna scenariointervall','simulate','primary')+'</div>'+note('Intervallet är ett <strong>antagandebaserat scenariointervall</strong>, inte ett statistiskt konfidensintervall från RVU eller en validering av modellen. Standardvärdena för variation är uttryckliga modellval.',true,true)+(s?'<div class="cards">'+kpi('P2,5 per hushåll',fmt(s.p025/denom,2),'ton CO₂e/år','Nedre gräns i simuleringens scenariointervall')+kpi('Central beräkning',fmt(selectedSubject().annual_ton_hh,2),'ton CO₂e/år','Beräkning med angivna centrala värden')+kpi('P97,5 per hushåll',fmt(s.p975/denom,2),'ton CO₂e/år','Övre gräns i simuleringens scenariointervall')+kpi('Reproducerbar simulering',fmt(u.draws),'dragningar','Slumptalsfrö '+u.seed)+'</div><p class="mini-text">'+esc(u.correlation)+'</p>':'<p class="mini-text">Intervallet beräknas på begäran. Ändrade inställningar tar bort ett tidigare intervall så att resultat från olika scenarier inte blandas.</p>')+'</section>';}
function comparisonPanel(){const a=state.result.areas.find(r=>r.id===state.compareA),b=state.result.areas.find(r=>r.id===state.compareB);const fields=[['Tillgänglighet','availability',0,'index'],['Bilar per hushåll','cars_per_household',2,'bilar/hh'],['Hushållsstorlek','household_size',2,'personer/hh'],['Årsutsläpp per hushåll','annual_ton_hh',2,'ton CO₂e/(hh·år)'],['Årsutsläpp per invånare','annual_ton_person',2,'ton CO₂e/person·år'],['Period per hushåll','period_ton_hh',1,'ton CO₂e/hh']];return '<section class="panel"><h2>Två områden sida vid sida</h2><div class="two-col"><div><label for="compare-a">Område A</label><select id="compare-a">'+regionOptions(state.compareA,false)+'</select></div><div><label for="compare-b">Område B</label><select id="compare-b">'+regionOptions(state.compareB,false)+'</select></div></div><div class="table-scroll" style="margin-top:18px"><table><thead><tr><th>Mått</th><th class="num">A</th><th class="num">B</th><th class="num">B − A</th></tr></thead><tbody>'+fields.map(([label,key,n,unit])=>'<tr><td>'+label+'<small>'+unit+'</small></td><td class="num">'+fmt(a[key],n)+'</td><td class="num">'+fmt(b[key],n)+'</td><td class="num">'+fmt(a[key]==null||b[key]==null?null:b[key]-a[key],n)+'</td></tr>').join('')+'</tbody></table></div><p class="mini-text">Områdenas olika boendeprofiler behålls. Jämförelsen beskriver därför inte samma standardhushåll på två olika platser.</p></section>';}
function inputNumber(key,label,help,min,max,step=1,scale=1){const value=state.config[key]/scale;return '<div class="form-field"><label for="cfg-'+key+'">'+label+'</label><input id="cfg-'+key+'" type="number" data-cfg="'+key+'" data-scale="'+scale+'" value="'+value+'" min="'+min+'" max="'+max+'" step="'+step+'"><p>'+help+'</p></div>';}
function selectField(key,label,help,options){return '<div class="form-field"><label for="cfg-'+key+'">'+label+'</label><select id="cfg-'+key+'" data-cfg="'+key+'">'+Object.entries(options).map(([v,l])=>'<option value="'+v+'"'+(v===state.config[key]?' selected':'')+'>'+l+'</option>').join('')+'</select><p>'+help+'</p></div>';}
function renderScenario(){const c=state.config;return hero('Antaganden & scenario','Alla beräkningsval är synliga','De befintliga hushållens egenskaper behålls. Du väljer hur resevolymen fördelas, vilka klimatfaktorer som används och hur resandet utvecklas under perioden.')+'<form id="scenario-form"><section class="panel"><h2>Referens och analysperiod</h2><div class="form-grid">'+inputNumber('start_year','Första analysår','Basunderlaget är 2024. Senare år är scenarioår.',2024,2100,1)+inputNumber('years','Antal år','Perioden inkluderar startåret och avslutas startår + antal år − 1.',1,100,1)+inputNumber('target_year','Målår för utvecklingsscenariot','Mellan basår 2024 och målår sker en linjär förändring.',2025,2200,1)+selectField('allocation','Geografisk fördelning','Registerläget använder bilinnehav för bil och åldersproxy för övriga. Tillgänglighetsläget använder dessutom antagna samband.',{register:'Registerbaserad fördelning',accessibility:'Tillgänglighetsfördelning · scenario'})+inputNumber('days_per_year','Dagar i modellåret','365 är ett uttryckligt årsantagande, inte en observation av hela året.',1,366,1)+inputNumber('season_factor','Säsongs- och årsöverföring','1 innebär ingen justering av undersökningsperiodens dygnsvärden.',0,5,.05)+inputNumber('excluded_age_addition','Tillägg för ej undersökta åldrar, %','0 innebär att yngre än 15 och äldre än 84 år inte fått ett särskilt restillägg. Ett annat värde är ett antagande.',0,300,1,.01)+'</div>'+note('Åldersandelen 15–84 år finns här bara som kommunal proxy, överförd till varje DeSO. Den faktiska åldersfördelningen per DeSO och resande för barn saknas. Hushållsstorlek, bilinnehav och ekonomisk standard följer däremot underlagets områdesvärden.',true,true)+'</section><section class="panel"><h2>Klimatfaktorer och beläggning</h2><label class="check large"><input type="checkbox" data-cfg="include_air"'+(c.include_air?' checked':'')+'>Inkludera flygresor i klimatresultatet</label><p class="mini-text">Samma val finns i vänstermenyn. När flyg utesluts räknas dess personkilometer och utsläpp som noll i denna avgränsning. Övriga färdmedel ändras inte och inga ersättningsresor läggs till. Valet är ingen beräknad utsläppsminskning från en åtgärd.</p><p class="mini-text">Källornas systemgränser skiljer sig. Bilens faktor är överförd från Vägvis. Buss och tåg får samma regionala scope 1–3-proxy; det är inte två uppmätta modalspecifika LCA-faktorer. Ändringar är egna antaganden.</p><div class="form-grid">'+inputNumber('occupancy','Personer per bil','1,3 är en överförd beläggningsschablon från Skånetrafikens beräkningssida.',1,8,.1)+inputNumber('car_g_vkm','Bil, g CO₂e/fordonskm','Bruttofaktor '+fmt(D.defaults.car_g_vkm,3)+' från bilmodellens tillverkning och drift; ingen återvinningskredit dras av.',0,3000,.1)+inputNumber('cycle_g_pkm','Mekanisk cykel, g CO₂e/personkm','ADEME:s publicerade tillverkningsreferens är 0,17. Överförd fransk faktor.',0,1000,.01)+inputNumber('ebike_g_pkm','Elcykel, g CO₂e/personkm','ADEME:s publicerade avrundade referens är 11.',0,1000,.1)+inputNumber('ebike_share','Andel elcykel av cykelkilometer, %','Ingen lokal andel finns. 0 är mekanisk referens, inte ett påstående om Malmös faktiska cykelmix.',0,100,1,.01)+inputNumber('bus_g_pkm','Buss, g CO₂e/personkm','17,5 är ett medel för hela Skånetrafikens trafik, här använt som proxy.',0,3000,.1)+inputNumber('rail_g_pkm','Tåg, g CO₂e/personkm','Samma regionala proxy som för buss. Resor utanför Skåne kan ha annan faktor.',0,3000,.1)+inputNumber('air_g_pkm','Flyg med höghöjdseffekt, g CO₂e/personkm','185 är ADEME:s referens för 1 000–2 000 km, inte observerad Malmö-ruttmix.',0,3000,.1)+inputNumber('air_nonco2_fraction','Andel av flygfaktorn som tas bort utan höghöjd, %','83/185 i referensen. Ingen ytterligare multiplikation med en höghöjdsfaktor görs.',0,100,.1,.01)+selectField('other_method','Övriga färdmedels klimatfaktor','Gruppen omfattar alla ospecificerade färdmedel i RVU. Fördelningen mellan t.ex. moped, MC, färja och andra färdmedel är inte känd.',{land_average:'Härlett medel för landfärdmedel · proxy',custom:'Egen faktor · antagande'})+inputNumber('other_g_pkm','Egen faktor för Övrigt, g CO₂e/personkm','Används bara när Egen faktor valts. Noll är då ett aktivt antagande, inte ett saknat värde.',0,3000,.1)+'</div><label class="check large"><input type="checkbox" data-cfg="include_air_nonco2"'+(c.include_air_nonco2?' checked':'')+'>Ta med flygets höghöjdseffekt när flyg ingår</label><p class="mini-text">Detta är ett separat val från att inkludera flyg. Referensens flygfaktor innehåller redan höghöjdseffekten. Om rutan avmarkeras tas den angivna andelen bort en gång.</p></section><section class="panel"><h2>Resevolymer och framtida förändring</h2><label class="check large"><input type="checkbox" data-cfg="future_enabled"'+(c.future_enabled?' checked':'')+'>Aktivera utvecklingsscenario</label><p class="mini-text">1,00 betyder oförändrat. Aktivitetsandelen och faktorandelen interpoleras var för sig från 2024 till målåret och multipliceras. Förändrat antal hushåll, flyttningar och ny infrastruktur beräknas inte automatiskt.</p><div class="table-scroll"><table><thead><tr><th>Färdmedel</th><th class="num">Resande relativt RVU</th><th class="num">Aktivitet i målåret</th><th class="num">Klimatfaktor i målåret</th><th class="num">Faktorvariation CV, %</th></tr></thead><tbody>'+D.modes.map(m=>'<tr><td>'+modeShort[m.id]+'</td>'+['activity_scale','activity_target','factor_target','factor_cv'].map(key=>'<td class="num"><input type="number" aria-label="'+key+' '+modeShort[m.id]+'" data-map="'+key+'" data-mode="'+m.id+'" data-scale="'+(key==='factor_cv'?.01:1)+'" value="'+(key==='factor_cv'?c[key][m.id]*100:c[key][m.id])+'" min="0" max="'+(key==='factor_cv'?500:key==='activity_scale'?10:5)+'" step="'+(key==='factor_cv'?1:.05)+'"></td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="button-row">'+button('Visa illustrativt utvecklingsexempel','illustrative-future','subtle')+'</div><p class="mini-text">Exempelknappen fyller i antaganden för att pröva modellen. De är inte officiella prognoser eller beslutade utsläppsbanor.</p></section><section class="panel"><h2>Rumsliga samband och tillgänglighetsindex</h2><div class="form-grid">'+inputNumber('transit_beta','Utbudsexponent för buss och tåg','Används bara i tillgänglighetsfördelningen. 0,5 är ett valt scenarioantagande, inte skattat samband.',-2,2,.05)+inputNumber('service_beta','Serviceexponent för gång och cykel','Används bara i tillgänglighetsfördelningen. 0,25 är ett valt scenarioantagande.',-2,2,.05)+inputNumber('air_income_beta','Inkomstexponent för flyg','0 innebär att inkomsten inte antas styra flygresandet. Ett annat värde är ett scenario.',-2,2,.05)+'</div><p class="mini-text">Bilens valbara lokala körsträcka kommer från Vägvis antagna koefficienter: centrum 0,12, kollektivtrafik 0,08, service 0,08 och inkomst 0,10. Kommunens bilvägda ankare bevaras. Inga sådana koefficienter har skattats från lokal observerad körsträcka.</p><div class="form-grid">'+Object.entries(c.index_weights).map(([k,v])=>'<div class="form-field"><label>'+({supply:'Vikt kollektivtrafikutbud',service:'Vikt dagligvaruservice',node:'Vikt kollektivtrafiknod',centre:'Vikt centrumavstånd'})[k]+'</label><input type="number" data-map="index_weights" data-mode="'+k+'" value="'+v+'" min="0" max="100" step=".25"><p>Lika vikter är ett transparent modellval, inte en officiell transportnorm.</p></div>').join('')+'</div></section><section class="panel"><h2>Scenarioosäkerhet</h2><div class="form-grid">'+inputNumber('draws','Antal Monte Carlo-dragningar','0 stänger av simuleringen. Variationskoefficienterna är antaganden.',0,3000,100)+inputNumber('seed','Slumptalsfrö','Samma frö och samma indata ger samma resultat i Python och webbläsaren.',0,4294967295,1)+inputNumber('demand_cv','Gemensam variation i resevolym, CV %','20 % är ett illustrativt modellval. Inte RVU:s skattade urvalsfel.',0,200,1,.01)+inputNumber('local_cv','Lokal fördelningsvariation, CV %','25 % är ett illustrativt modellval. Lokal variation normaliseras så att färdmedlets kommunsumma bevaras.',0,200,1,.01)+'</div><label for="project-notes">Egna källor och anteckningar</label><textarea id="project-notes" placeholder="Dokumentera ändrade faktorer, resevolymer och antaganden.">'+esc(state.notes)+'</textarea></section><div class="button-row"><button class="btn primary" type="submit">Tillämpa och beräkna</button><button class="btn" type="button" data-action="reset">Återställ standardvärden</button></div></form>';}
function sourceStatus(s){return s.status==='primary_published'?'<span class="status good">Publicerad primärkälla</span>':s.status==='explicit_model_choice'?'<span class="status proxy">Modellval</span>':'<span class="status proxy">Överfört från bilaga</span>';}
function referencesHTML(){return '<ol class="source-list">'+[...D.sources].sort((a,b)=>a.author.localeCompare(b.author,'sv')||a.year.localeCompare(b.year,'sv')||a.title.localeCompare(b.title,'sv')).map(s=>'<li id="source-'+s.id+'"><strong>'+esc(s.author)+' ('+esc(s.year)+').</strong> <em>'+esc(s.title)+'.</em> '+(s.url?'<a href="'+esc(s.url)+'" target="_blank" rel="noopener">Öppna källa ↗</a>':'Användarlevererat underlag eller öppen modellkod.')+' '+sourceStatus(s)+'<p>'+esc(s.use)+(s.locator?' <strong>Lokalisering:</strong> '+esc(s.locator):'')+' Hämtad/läst: '+s.accessed+'.</p></li>').join('')+'</ol>';}
function factorTable(){const ef=state.result.factors_kg_pkm;const refs={walk:'ADEME, fordon/energi',cycle:'ADEME, cykelreferens och vald elcykelandel',car:'Vägvis brutto / vald bilbeläggning',bus:'Skånetrafiken scope 1–3, regional proxy',rail:'Skånetrafiken scope 1–3, regional proxy',air:'ADEME, med vald höghöjdsavgränsning',other:state.config.other_method==='custom'?'Användarens faktor':'Härlett genomsnitt för landfärdmedel'};return '<div class="table-scroll"><table><thead><tr><th>Färdmedel</th><th class="num">Aktiv faktor, g CO₂e/pkm</th><th>Referens och överföring</th></tr></thead><tbody>'+D.modes.map(m=>'<tr><td>'+modeShort[m.id]+'</td><td class="num">'+fmt(ef[m.id]*1000,3)+'</td><td>'+refs[m.id]+(m.id==='air'&&!state.config.include_air?' · flyg exkluderat från resultatet':'')+'</td></tr>').join('')+'</tbody></table></div>';}
function renderData(){const receipt=D.grid_receipt;return hero('Underlag & datakvalitet','Vad vet vi om varje område?','Registerdata, undersökningar och antaganden hålls isär. Du kan komplettera observerade personkilometer per DeSO och färdmedel, utan API-nycklar eller GitHub Workflows.')+'<div class="cards">'+kpi('DeSO med registerdata','209','områden','Hushåll, folkmängd och privatregistrerade bilar')+kpi('Rutnätets upplösning','250 × 250','meter','EPSG:3006 · '+fmt(receipt.unique_cells)+' unika rutor')+kpi('Hushåll per ruta','Saknas','','Inga cellbaserade hushållstal konstrueras')+kpi('Observerad lokal körsträcka','Saknas','','Kommunankare och valbar modellfördelning')+'</div><section class="panel"><h2>Datatäckning och begränsningar</h2><div class="table-scroll"><table><thead><tr><th>Underlag</th><th>Geografi och tid</th><th>Status</th></tr></thead><tbody><tr><td>Hushåll, invånare, bilar</td><td>209 DeSO, 2024</td><td><span class="status good">Registerdata i bilagan</span></td></tr><tr><td>Hushållsstorlek och bilar/hushåll</td><td>Härledda kvoter per DeSO</td><td><span class="status good">Beräknat från register</span></td></tr><tr><td>Median ekonomisk standard</td><td>209 DeSO, 2024</td><td><span class="status good">Områdesstatistik i bilagan</span></td></tr><tr><td>Personkilometer för sju färdmedel</td><td>Malmö RVU 2023, ålder 15–84</td><td><span class="status proxy">Kommunskattning → lokal fördelning</span></td></tr><tr><td>Ålderspopulation 15–84 per DeSO</td><td>Kommunandel 2023 överförd till DeSO</td><td><span class="status proxy">Lokal åldersfördelning saknas</span></td></tr><tr><td>Kollektivtrafikutbud</td><td>DeSO-medel, planerad vecka 2024-10-14–20</td><td><span class="status proxy">Inte restid eller årsmedel</span></td></tr><tr><td>Service och kollektivtrafiknod</td><td>DeSO-medel, OSM-geografiproxy 2026</td><td><span class="status proxy">Fågelväg, inte gångnät</span></td></tr><tr><td>Arbetsplatser inom 30 minuter</td><td>Ej tillgängligt i bilagorna</td><td><span class="status missing">Används inte</span></td></tr><tr><td>Hushåll och resande per 250 m-ruta</td><td>Ej tillgängligt i bilagorna</td><td><span class="status missing">Används inte som observerat</span></td></tr><tr><td>Parkeringsutbud, upplåtelseform, lokal ålder</td><td>Ingen harmoniserad förklaringsmodell</td><td><span class="status missing">Används inte</span></td></tr></tbody></table></div></section><section class="panel"><h2>Färdmedelsunderlag från Malmö RVU</h2><p class="mini-text">Region Skåne (2024), tabell 2 s. 29. Dessa personkilometer summerar till 10 758 200 per undersökningsdygn för 15–84-åringar. Antal resor och personkilometer är olika mått. Anslutningsresor redovisas under huvudfärdmedlet.</p><div class="table-scroll"><table><thead><tr><th>Huvudfärdmedel</th><th class="num">Personkilometer per dygn</th><th class="num">Resor per dygn</th></tr></thead><tbody>'+D.modes.map(m=>'<tr><td>'+esc(m.name)+'</td><td class="num">'+fmt(D.rvu.daily_pkm[m.id])+'</td><td class="num">'+fmt(D.rvu.trips_per_day[m.id])+'</td></tr>').join('')+'</tbody></table></div><p class="mini-text">Flyg finns i källunderlaget och kan inkluderas eller exkluderas i beräkningen. Moped, MC, färja, elsparkcykel, taxi och liknande kan inte urskiljas säkert som egna volymer i tabellen. De behålls inom RVU:s bil- eller övrigtgrupp enligt undersökningens klassning, utan en extra påhittad resevolym.</p></section><section class="panel"><h2>Aktiva klimatfaktorer</h2>'+factorTable()+note('Totalen är en screening med blandade systemgränser. Den är inte en fullständig eller certifierad cradle-to-cradle-beräkning. Tillverkning, infrastruktur och övriga värdekedjor behandlas olika i källorna. Dessa skillnader försvinner inte genom att faktorerna summeras.',true,true)+'</section><section class="panel"><h2>Komplettera resande per DeSO</h2><p class="mini-text">CSV-kolumner: <code>deso;mode;pkm_year;year;source</code>. Färdmedelskoder: walk, cycle, car, bus, rail, air, other. Ange personkilometer per <strong>år för hela DeSO-området</strong>, inte per person eller fordon. År ska vara 2024. Tomma mallrader ignoreras. Två värden för samma DeSO och färdmedel i en fil ger ett tydligt fel.</p><div class="button-row">'+button('Hämta kompletteringsmall','export-template')+button('Läs in personkilometer · CSV','import-activity','primary')+(state.overrides.length?button('Ta bort kompletterade resevolymer','clear-overrides','danger'):'')+'</div><p class="mini-text">'+fmt(state.overrides.length)+' kompletterade värden. En komplettering ersätter hela färdmedlets årsvärde i berört DeSO. Kommunens totalsumma får då ändras; egna värden normaliseras inte bort.</p></section><section class="panel"><h2>Exportera och spara</h2><div class="button-row">'+button('DeSO-resultat · CSV','export-csv')+button('250 m-rutor · GeoJSON','export-geojson')+button('DeSO-lager · GeoJSON','export-deso-geojson')+button('Alla beräkningar · JSON','export-result')+button('Interaktiv karta med mina inställningar','export-html')+button('Projektinställningar · JSON','save-project')+'</div><p class="mini-text">Projektfilen kan öppnas i appen eller användas med Pythonkodens <code>--projekt</code>. Resultat-CSV och GeoJSON är jämförelseunderlag för GIS, Vägvis och Road2Zero; automatisk import i deras ordinarie projektformat har inte byggts i denna version.</p></section><section class="panel"><h2>Geometrikontroll</h2><p class="mini-text">'+fmt(receipt.unique_cells)+' rutor, '+fmt(receipt.cell_fragments)+' DeSO-avskilda rutfragment. Analysyta '+fmt(receipt.land_m2/10000,2)+' ha utan hav. Skillnad mellan summan av rutfragmentens yta och DeSO-ytorna: '+fmt(Math.abs(receipt.closure_error_m2),6)+' m². Arean beräknas före visningsförenkling.</p><p class="mini-text">Gränserna är SCB:s 2025_v2. Landmasken kommer från OpenStreetMap och omfattar inlandsvatten. Geometrireparation och kustavskiljning är geometriska bearbetningar; de innebär inte att befolkningsdata har förbättrats.</p></section>';}
function renderMethod(){return hero('Beräkningsbeskrivning & källor','Så räknar Lägesvis Malmö','En fristående, öppen modell med dokumenterade enheter, systemgränser, överföringar och antaganden. Inga regressionskoefficienter har skattats från observerad lokal körsträcka.')+'<article class="method">'+$('method-template').innerHTML+'<h2>Aktiva faktorer i denna körning</h2>'+factorTable()+'<h2>Aktiva inställningar</h2><p>Denna lista följer det öppnade projektet. Ändrade värden ska tolkas som egna antaganden om ingen ny källa har dokumenterats.</p><pre class="code-box">'+esc(JSON.stringify(state.config,null,2))+'</pre><h2>Referenslista i Harvard-format</h2>'+referencesHTML()+'<h2>Licenser och återanvändning</h2><p>Ny Python- och JavaScriptkod: MIT. SCB:s öppna geodata behåller sin källangivelse. Landmask och härledda geografiska underlag: © OpenStreetMap contributors, <a href="https://opendatacommons.org/licenses/odbl/1-0/" target="_blank" rel="noopener">ODbL 1.0</a>. Leaflet behåller BSD-2-Clause-licensen. Vägvis motorkod används endast vid framtagning av det frysta referensunderlaget och behåller sin MIT-licens.</p><details><summary>Visa medföljande licenstexter</summary><pre class="code-box">'+esc(D.licences.leaflet+'\n\n'+D.licences.vagvis)+'</pre></details></article>';}
function disposeMap(){if(map){map.remove();map=null;}mapLayers=[];}
function render(){disposeMap();$('sidebar-scope').textContent=pageScope();$('include-air-toggle').checked=state.config.include_air;const names={overview:'Översikt',map:'Karta & områden',results:'Resultat & jämförelse',scenario:'Antaganden & scenario',data:'Underlag & datakvalitet',method:'Metod & källor'};$('page-name').textContent=names[state.page];document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('content').innerHTML=({overview:renderOverview,map:renderMap,results:renderResults,scenario:renderScenario,data:renderData,method:renderMethod})[state.page]();if($('map-surface'))drawMap();bindPage();}
function navigate(page){state.page=page;document.querySelector('.sidebar').classList.remove('mobile-open');render();document.querySelector('.main').scrollTop=0;}
function metricFor(g,rows){const r=rows[g.deso||g.id];if(state.metric==='availability'&&g.deso)return M.availability(D,state.config,pBy[g.deso],g.centre_km).score;return r[state.metric];}
function drawMap(){disposeMap();if(!window.L){$('map-surface').innerHTML='<div class="empty">Kartbiblioteket kunde inte startas. Områdestabellen och beräkningen fungerar ändå.</div>';return;}const rows=Object.fromEntries(state.result.areas.map(r=>[r.id,r])),metric=metrics[state.metric],geoms=state.layer==='grid'?D.cells:D.areas,vals=state.result.areas.map(r=>r[state.metric]).filter(x=>x!=null),min=state.metric==='availability'?0:Math.min(...vals),max=state.metric==='availability'?100:Math.max(...vals),colors=metric.inverse?['#377f68','#92b286','#c4ca94','#e0bb83','#ba745a']:['#e2eddb','#aac39f','#79a78b','#397e67','#103c38'];
 const color=v=>{if(v==null)return '#cbd3ce';const f=max===min?.5:Math.max(0,Math.min(1,(v-min)/(max-min)));return colors[Math.min(4,Math.floor(f*5))];};map=L.map('map-surface',{scrollWheelZoom:false,preferCanvas:true,zoomSnap:.25,attributionControl:true});
 if(state.osm){let failures=0;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'}).on('tileerror',()=>{if(++failures>2&&$('map-note'))$('map-note').textContent='Bakgrundskartan kunde inte hämtas. Rutnät, DeSO och beräkningar fungerar lokalt.';}).addTo(map);}
 const fc={type:'FeatureCollection',features:geoms.map(g=>({type:'Feature',properties:{id:g.id,deso:g.deso||g.id},geometry:g.geometry}))};
 const objBy=Object.fromEntries(geoms.map(g=>[g.id,g]));const style=f=>{const g=objBy[f.properties.id],code=g.deso||g.id;return{fillColor:color(metricFor(g,rows)),color:code===state.selected?'#0b4033':'#fff',weight:code===state.selected?1.7:state.layer==='grid'?.35:1,fillOpacity:state.osm?.7:.93,opacity:.9};};
 const layer=L.geoJSON(fc,{style,onEachFeature(f,l){const g=objBy[f.properties.id],code=f.properties.deso,r=rows[code],value=metricFor(g,rows),tip='<b>'+esc(r.name)+'</b><br>'+code+'<br>'+fmt(value,metric.digits)+' '+esc(metric.unit)+(g.cell_id?'<br><small>Ruta '+g.cell_id+' · klimatprofil från DeSO</small>':'');l.bindTooltip(tip,{sticky:true,className:'map-tip'});l.on('click',()=>{state.selected=code;const p=pBy[code];const html=tip+'<br><hr><b>DeSO:s boendeprofil 2024</b><br>'+fmt(r.households)+' hushåll · '+fmt(r.population)+' invånare<br>'+fmt(r.household_size,2)+' personer/hushåll<br>'+fmt(r.cars_per_household,2)+' privatregistrerade bilar/hushåll<br>'+fmt(r.annual_ton_hh,2)+' ton CO₂e/(hushåll·år)<br>'+fmt(r.period_ton_hh,1)+' ton CO₂e/hushåll under '+state.config.years+' år<br><small>Ingen observerad befolkning eller hushållsvolym i rutan. Geografisk profil och antaganden är områdesbaserade.</small>';L.popup({maxWidth:340}).setLatLng(l.getBounds().getCenter()).setContent(html).openOn(map);if($('region-select'))$('region-select').value=code;layer.setStyle(style);if($('map-details'))$('map-details').innerHTML=detailsPanel();});mapLayers.push(l);}}).addTo(map);
 const bounds=state.selected?L.geoJSON(aBy[state.selected].geometry).getBounds():L.geoJSON({type:'FeatureCollection',features:D.areas.map(a=>({type:'Feature',geometry:a.geometry}))}).getBounds();map.fitBounds(bounds,{padding:[17,17],maxZoom:14});
 map.attributionControl.addAttribution('SCB DeSO 2025 · © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OSM land, ODbL</a>');const legend=L.control({position:'bottomright'});legend.onAdd=()=>{const div=L.DomUtil.create('div','legend');div.innerHTML='<b>'+esc(metric.unit)+'</b><div class="legend-ramp '+(metric.inverse?'climate':'')+'"></div><div class="legend-labels"><span>'+fmt(min,metric.digits)+'</span><span>'+fmt(max,metric.digits)+'</span></div><small>'+((state.metric==='availability')?'Relativt index · högre = bättre utbud och närhet':'Relativ skala för aktuellt kartlager')+'</small>';L.DomEvent.disableClickPropagation(div);return div;};legend.addTo(map);setTimeout(()=>map?.invalidateSize(),70);
}
function bindPage(){$('include-air-toggle').onchange=e=>{state.config.include_air=e.target.checked;calculate();render();toast(state.config.include_air?'Flygresor ingår i resultatet.':'Flygresor är exkluderade. Övriga färdmedel är oförändrade.');};if($('metric-select'))$('metric-select').onchange=e=>{state.metric=e.target.value;drawMap();};if($('osm-toggle'))$('osm-toggle').onchange=e=>{state.osm=e.target.checked;drawMap();};if($('region-select'))$('region-select').onchange=e=>{state.selected=e.target.value;render();};for(const side of ['a','b'])if($('compare-'+side))$('compare-'+side).onchange=e=>{state[side==='a'?'compareA':'compareB']=e.target.value;render();};if($('table-search'))$('table-search').oninput=e=>{state.tableSearch=e.target.value;$('results-table').innerHTML=resultsTable();};if($('scenario-form'))$('scenario-form').onsubmit=e=>{e.preventDefault();try{const c=M.copy(state.config);for(const el of e.currentTarget.querySelectorAll('[data-cfg]')){const k=el.dataset.cfg;c[k]=el.type==='checkbox'?el.checked:el.type==='number'?el.valueAsNumber*Number(el.dataset.scale||1):el.value;}for(const el of e.currentTarget.querySelectorAll('[data-map]'))c[el.dataset.map][el.dataset.mode]=el.valueAsNumber*Number(el.dataset.scale||1);state.config=M.validateConfig(D,c);state.notes=$('project-notes').value;calculate();render();toast('Inställningarna har tillämpats.');}catch(err){message('Inställningarna kunde inte användas',err.message);}};}
function download(name,content,type='application/json'){const blob=new Blob([content],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);toast('Hämtar '+name);}
function csv(rows){if(!rows.length)return '';const fields=Object.keys(rows[0]),cell=x=>{if(x==null)return '';let s=typeof x==='object'?JSON.stringify(x):String(x);if(typeof x==='string'&&/^[=+@-]/.test(s))s="'"+s;return /[;"\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;};return '\ufeff'+fields.map(cell).join(';')+'\r\n'+rows.map(r=>fields.map(k=>cell(r[k])).join(';')).join('\r\n');}
function project(){return{schema:'lagesvis-project-1',version:M.VERSION,base_year:D.base_year,config:M.copy(state.config),overrides:M.copy(state.overrides),notes:state.notes,source_hashes:D.source_hashes};}
function exportRows(){return state.result.areas.map(r=>{const out={};for(const [k,v]of Object.entries(r))if(!['mode_pkm','mode_tons'].includes(k))out[k]=v;for(const m of M.MODE_IDS){out['pkm_base2024_'+m]=r.mode_pkm[m];out['ton_'+m]=r.mode_tons[m];}Object.assign(out,{analysis_year:state.config.start_year,period_years:state.config.years,scope:state.result.scope,units:state.result.units,factors_kg_pkm:state.result.factors_kg_pkm,model_config:state.config,source_sha256:D.source_hashes});return out;});}
function geojson(layer){const rows=Object.fromEntries(state.result.areas.map(r=>[r.id,r]));return{type:'FeatureCollection',name:layer==='grid'?'Lagesvis_Malmo_250m':'Lagesvis_Malmo_DeSO',metadata:{...project(),coordinate_reference_system:'OGC:CRS84 longitude latitude',metric_grid_crs:'EPSG:3006',cell_size_m:250,population_and_households_per_cell:null,scope:state.result.scope,grid_receipt:D.grid_receipt},features:(layer==='grid'?D.cells:D.areas).map(g=>{const r=rows[g.deso||g.id];return{type:'Feature',geometry:g.geometry,properties:{id:g.id,cell_id:g.cell_id??null,deso:g.deso||g.id,name:r.name,analysis_year:state.config.start_year,period_years:state.config.years,land_m2:g.land_m2,availability:layer==='grid'?M.availability(D,state.config,pBy[r.id],g.centre_km).score:r.availability,annual_ton_hh:r.annual_ton_hh,annual_ton_person:r.annual_ton_person,period_ton_hh:r.period_ton_hh,profile_level:'DeSO 2025',include_air:state.config.include_air,include_air_nonco2:state.config.include_air_nonco2,grid_population:null,grid_households:null,deso_household_size:r.household_size,deso_cars_per_household:r.cars_per_household}};})};}
function parseCSV(text){text=text.replace(/^\ufeff/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(ch==='"')quoted=false;else cell+=ch;}else if(ch==='"')quoted=true;else if(ch===';'){row.push(cell);cell='';}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw new Error('CSV-filen har ett oavslutat citattecken.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(!rows.length)throw new Error('CSV-filen är tom.');const fields=rows.shift().map(x=>x.trim());if(new Set(fields).size!==fields.length)throw new Error('Dubbla kolumnrubriker i CSV.');return rows.map(r=>{if(r.length!==fields.length)throw new Error('CSV-raden har fel antal kolumner.');return Object.fromEntries(fields.map((k,i)=>[k,r[i].trim()]));});}
function importActivity(text){const records=parseCSV(text),rows=[];for(const r of records){for(const k of ['deso','mode','pkm_year','year','source'])if(!(k in r))throw new Error('Kolumnen '+k+' saknas.');if(!r.pkm_year&&!r.source)continue;if(!r.pkm_year)throw new Error('En rad med källa saknar personkilometer.');rows.push({deso:r.deso,mode:r.mode,pkm_year:Number(r.pkm_year.replace(',','.')),year:Number(r.year),source:r.source});}const checked=M.validateOverrides(D,rows),merged=new Map(state.overrides.map(r=>[r.deso+'|'+r.mode,r]));for(const row of checked)merged.set(row.deso+'|'+row.mode,row);state.overrides=[...merged.values()];calculate();render();toast(checked.length+' kompletterade värden har lästs in.');}
async function doAction(action){if(action==='go-scenario')return navigate('scenario');if(action==='go-map')return navigate('map');if(action==='clear-selection'){state.selected='';return render();}if(action==='map-fit'){state.selected='';if($('region-select'))$('region-select').value='';return drawMap();}
 if(action==='save-project')return download('Lagesvis_projekt.json',JSON.stringify(project(),null,2));
 if(action==='export-csv')return download('Lagesvis_Malmo_DeSO.csv',csv(exportRows()),'text/csv');
 if(action==='export-result')return download('Lagesvis_berakning.json',JSON.stringify({schema:'lagesvis-result-1',project:project(),result:state.result,uncertainty:state.uncertainty,sources:D.sources},null,2));
 if(action==='export-geojson'||action==='export-deso-geojson')return download(action==='export-geojson'?'Lagesvis_Malmo_250m.geojson':'Lagesvis_Malmo_DeSO.geojson',JSON.stringify(geojson(action==='export-geojson'?'grid':'deso')),'application/geo+json');
 if(action==='export-template')return download('Lagesvis_personkilometer_mall.csv',csv(D.profiles.flatMap(p=>M.MODE_IDS.map(m=>({deso:p.id,mode:m,pkm_year:'',year:2024,source:''})))),'text/csv');
 if(action==='import-activity')return $('activity-file').click();
 if(action==='clear-overrides'){state.overrides=[];calculate();render();return toast('Kompletteringarna har tagits bort.');}
 if(action==='reset'){state.config=M.validateConfig(D);calculate();render();return toast('Standardinställningar återställda. Dina kompletteringar finns kvar.');}
 if(action==='illustrative-future'){state.config.future_enabled=true;state.config.activity_target={walk:1.15,cycle:1.3,car:.8,bus:1.2,rail:1.3,air:.8,other:1};state.config.factor_target={walk:1,cycle:.8,car:.4,bus:.6,rail:.7,air:.8,other:.8};calculate();render();return toast('Illustrativa antaganden valda. Detta är ingen officiell prognos.');}
 if(action==='simulate'){if(busy)return;if(!state.config.draws)return message('Simuleringen är avstängd','Ange fler än noll dragningar under Antaganden & scenario.');busy=true;const button=document.querySelector('[data-action="simulate"]');if(button){button.disabled=true;button.textContent='Beräknar …';}await new Promise(resolve=>setTimeout(resolve,40));try{state.uncertainty=M.simulate(D,state.result);render();toast('Scenariointervallet har beräknats.');}finally{busy=false;}return;}
 if(action==='export-html'){const clone=document.documentElement.cloneNode(true);clone.querySelector('#python-baseline').textContent=JSON.stringify({...state.result,ui_notes:state.notes}).replace(/[<>&]/g,ch=>String.fromCharCode(92)+({"<":"u003c",">":"u003e","&":"u0026"})[ch]);clone.querySelector('#toast').style.display='none';const dialog=clone.querySelector('dialog');dialog.removeAttribute('open');download('Lagesvis_Malmo_min_karta.html','<!doctype html>\n'+clone.outerHTML,'text/html');}
