document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){e.preventDefault();return navigate(page.dataset.page);}const layer=e.target.closest('[data-layer]');if(layer){state.layer=layer.dataset.layer;render();return;}const select=e.target.closest('[data-select]');if(select){state.selected=select.dataset.select;return navigate('map');}const action=e.target.closest('[data-action]');if(action){e.preventDefault();Promise.resolve(doAction(action.dataset.action)).catch(err=>message('Åtgärden kunde inte genomföras',err.message));}});
$('open-project').onclick=()=>$('project-file').click();$('save-project').onclick=()=>doAction('save-project');$('mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('mobile-open');
$('project-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw new Error('Projektfilen är större än 5 MB.');const p=JSON.parse(await file.text());if(p.schema!=='lagesvis-project-1'||p.base_year!==2024)throw new Error('Projektfilen har fel schema eller basår.');const cfg=M.validateConfig(D,p.config),overrides=M.validateOverrides(D,p.overrides||[]);state.config=cfg;state.overrides=overrides;state.notes=String(p.notes||'');calculate();render();toast('Projektet har öppnats.');}catch(err){message('Projektet kunde inte öppnas',err.message);}finally{e.target.value='';}};
$('activity-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw new Error('CSV-filen är större än 5 MB.');importActivity(await file.text());}catch(err){message('Kompletteringen kunde inte läsas',err.message);}finally{e.target.value='';}};
render();
})();
